const now=Date.parse('2026-10-22T14:50:00Z'),job_id='job_11111111-1111-4111-8111-111111111111',request_id='acl_'+'a'.repeat(64),draft_id='b'.repeat(32),binding={revision:2,mode_epoch:3,script_hash:'c'.repeat(64),contract_hash:'d'.repeat(64)},speech_text_sha256='e'.repeat(64);
function fixture(t){const root=fs.mkdtempSync(path.join(os.tmpdir(),'SYNTHETIC-provider-editor-')),dir=path.join(root,job_id,'revision-2','automatic-clone',request_id);fs.mkdirSync(dir,{recursive:true});t.after(()=>fs.rmSync(root,{recursive:true,force:true}));return{...writeProviderEditorHistory({dir,request_id,binding,speech_text_sha256,draft_id,clock:()=>now}),root};}
const permit=(f,c)=>({...f.input,attempt_dir:c.dir,permit:{evidence:c.evidence,journal_sha256:c.journal_sha256}});
const snapshot=dir=>Object.fromEntries(fs.readdirSync(dir,{recursive:true}).filter(name=>fs.statSync(path.join(dir,name)).isFile()).sort().map(name=>[name,previewSha(fs.readFileSync(path.join(dir,name)))]));
const noIntent=f=>assert.equal(fs.existsSync(path.join(f.dir,PROVIDER_EDITOR_INTENT_FILE)),false);
function complete(f,{audio,timeout=false,readonly=false}={}){
 const claim=claimProviderEditorContinuation(f.lockInput());assert.ok(claim,'fixture requires one authorized official editor transfer');
 writeProviderEditorTransfer(f,claim);
 let verification=finishProviderEditorAttempt(f,claim,timeout?{accepted:false,timed_out:true,exit_code:null}:{});
 if(readonly)verification=finishProviderEditorAttempt(f,claim,{name:'readiness-44444444-4444-4444-8444-444444444444',phase:'preview-readiness',started_at:now+100,finished_at:now+150});
 const persistence=writeProviderEditorPersistence(f,claim,verification,{...(audio?{current_audio:audio}:{}),verified_at:readonly?now+160:now+60});
 return{claim,verification,persistence};
}

