function directPersistenceFixture(t,{audio}={}){const f=directAccessFixture(t),input=f.directInput();if(audio)input.current_audio=audio;const certificate=createProviderEditorDirectPersistence(input);assert.ok(certificate,'fixture requires complete typed fresh direct access');assert.equal(fs.existsSync(path.join(f.dir,PROVIDER_EDITOR_DIRECT_PERSISTENCE_FILE)),false);f.write(PROVIDER_EDITOR_DIRECT_PERSISTENCE_FILE,certificate);f.directCertificate=certificate;f.input.clock=()=>now+1000;f.previewAuthorization=writeProviderOwnerPreviewAuthorization(f,{persistence_file:PROVIDER_EDITOR_DIRECT_PERSISTENCE_FILE});return f;}

test('direct-access persistence creation is pure and records no editor transfer or consumed editor opportunity',t=>{const f=directAccessFixture(t),before=snapshot(f.dir),certificate=createProviderEditorDirectPersistence(f.directInput());assert.ok(certificate);assert.equal(certificate.provider_editor_access,'direct');assert.equal(certificate.editor_transfer_count,0);assert.equal(certificate.editor_transfer_observed,false);assert.equal(certificate.editor_opportunity_consumed,false);assert.deepEqual(snapshot(f.dir),before);f.write(PROVIDER_EDITOR_DIRECT_PERSISTENCE_FILE,certificate);const proof=inspectProviderEditorDirectPersistence({...f.input,clock:()=>now+1000});assert.ok(proof);assert.equal(proof.persistence_origin,'provider-editor-direct-access');assert.equal(proof.verification_attempt,f.directAccess.name);assert.equal(proof.persistence_evidence_sha256,previewSha(fs.readFileSync(path.join(f.dir,PROVIDER_EDITOR_DIRECT_PERSISTENCE_FILE))));assert.equal(proof.new_play_allowed,false);assert.equal(proof.previous_preview_outcome,'unchanged-unknown');assert.equal(fs.existsSync(path.join(f.dir,PROVIDER_EDITOR_INTENT_FILE)),false);assert.equal(fs.existsSync(path.join(f.dir,PROVIDER_EDITOR_TRANSFER_FILE)),false);assert.equal('repair_intent_sha256'in certificate,false);});

test('direct-access v2 source permits one extra preview while creating zero editor journals and retaining old unknown Play',t=>{const f=directPersistenceFixture(t),before=snapshot(f.dir),proof=inspectOwnerPreviewContinuation(f.input);assert.ok(proof);assert.equal(proof.persistence_attempt,f.directAccess.name);assert.equal(proof.direct_persistence_sha256,f.previewAuthorization.manifest.persistence_evidence_sha256);assert.equal('repair_attempt'in proof,false);assert.equal('repair_intent_sha256'in proof,false);assert.equal(proof.previous_preview_outcome,'unchanged-unknown');const claim=claimOwnerPreviewContinuation(f.input);assert.ok(claim);assert.equal(claim.evidence.maximum_extra_play_count,1);assert.equal(validateOwnerPreviewContinuationPermit(permit(f,claim)),true);assert.equal(claimOwnerPreviewContinuation(f.input),null);assert.equal(fs.existsSync(path.join(f.dir,PROVIDER_EDITOR_INTENT_FILE)),false);assert.equal(fs.existsSync(path.join(f.dir,PROVIDER_EDITOR_TRANSFER_FILE)),false);const after=snapshot(f.dir);delete after[OWNER_PREVIEW_CONTINUATION_JOURNAL];assert.deepEqual(after,before);});

test('direct-access source remains verifiable after its one extra attempt and actual Play marker for read-only outcome recovery',t=>{
 const f=directPersistenceFixture(t),originals=f.originalBytes(),certificate=fs.readFileSync(path.join(f.dir,PROVIDER_EDITOR_DIRECT_PERSISTENCE_FILE)),claim=claimOwnerPreviewContinuation(f.input);assert.ok(claim);const verification=finishProviderEditorAttempt(f,claim,{phase:'preview',started_at:now+1001,finished_at:now+1100,accepted:false,exit_code:1});f.patch(verification.name+'/browser-events.json',s=>s.play_journal_saved=true);
 f.write(OWNER_EXTRA_PLAY_OBSERVED_FILE,{schema:'heygen-studio-owner-extra-play-observed-v1',request_id,draft_id,speech_text_sha256,voice_id:f.input.voice_id,voice_name:'Siounex口播',authorization_nonce:claim.evidence.authorization_nonce,continuation_journal_sha256:claim.journal_sha256,clicked_at:new Date(now+1020).toISOString(),play_clicked:true});
 const input={...f.input,clock:()=>now+2000},outcome=inspectOwnerPreviewContinuationOutcome(input);assert.ok(outcome);assert.equal(outcome.extra_play_observed,true);assert.equal(outcome.extra_opportunity_consumed,true);assert.equal(outcome.new_play_allowed,false);assert.equal(outcome.maximum_new_play_count,0);assert.equal(claimOwnerPreviewContinuation(input),null);assert.deepEqual(fs.readFileSync(path.join(f.dir,PROVIDER_EDITOR_DIRECT_PERSISTENCE_FILE)),certificate);assert.deepEqual(f.originalBytes(),originals);assert.equal(fs.existsSync(path.join(f.dir,PROVIDER_EDITOR_INTENT_FILE)),false);assert.equal(fs.existsSync(path.join(f.dir,PROVIDER_EDITOR_TRANSFER_FILE)),false);
});

test('direct-access source resumes later existing audio without any repair record or extra Play consumption',t=>{
 const f=directPersistenceFixture(t,{audio:{present:true,ready_state:4,duration_seconds:4.25,media_url_sha256:'7'.repeat(64),generation_in_progress:false}}),verification=finishProviderEditorAttempt(f,{dir:path.join(f.dir,'readiness-55555555-5555-4555-8555-555555555555')},{name:'readiness-55555555-5555-4555-8555-555555555555',phase:'preview-readiness',started_at:now+100,finished_at:now+150}),originals=f.originalBytes();
 f.write(OWNER_EXISTING_AUDIO_PROOF_FILE,{schema:'heygen-studio-owner-existing-audio-proof-v1',request_id,binding,draft_id,speech_text_sha256,voice_id:f.input.voice_id,authorization_file_sha256:f.previewAuthorization.sha256,authorization_nonce:f.previewAuthorization.manifest.authorization_nonce,readiness_attempt:verification.name,browser_evidence_sha256:verification.evidence,media_url_sha256:'7'.repeat(64),duration_seconds:4.25,observed_at:new Date(now+140).toISOString(),ready_state:4,play_clicked:false,extra_play_count:0,new_play_allowed:false,previous_preview_outcome:'unchanged-unknown',history_reinterpreted:false});
 const proof=inspectOwnerPreviewExistingAudio(f.input);assert.ok(proof);assert.equal(proof.existing_audio_verified,true);assert.equal(proof.extra_play_count,0);assert.equal(proof.new_play_allowed,false);assert.equal(claimOwnerPreviewContinuation(f.input),null);assert.equal(fs.existsSync(path.join(f.dir,OWNER_PREVIEW_CONTINUATION_JOURNAL)),false);assert.equal(fs.existsSync(path.join(f.dir,PROVIDER_EDITOR_INTENT_FILE)),false);assert.equal(fs.existsSync(path.join(f.dir,PROVIDER_EDITOR_TRANSFER_FILE)),false);assert.deepEqual(f.originalBytes(),originals);
});

for(const [label,change]of [
 ['unknown old editor intent',f=>f.write(PROVIDER_EDITOR_INTENT_FILE,{schema:'SYNTHETIC-unknown-editor-intent'})],['unknown old editor transfer marker',f=>f.write(PROVIDER_EDITOR_TRANSFER_FILE,{schema:'SYNTHETIC-unknown-transfer-marker'})],['missing direct-access typed flag',f=>f.patch(f.directAccess.name+'/browser-events.json',s=>delete s.validation.provider_editor_direct_access_accepted)],['false direct-access typed flag',f=>f.patch(f.directAccess.name+'/browser-events.json',s=>s.validation.provider_editor_direct_access_accepted=false)],['string direct-access typed flag',f=>f.patch(f.directAccess.name+'/browser-events.json',s=>s.validation.provider_editor_direct_access_accepted='true')],['missing same-draft reload typed flag',f=>f.patch(f.directAccess.name+'/browser-events.json',s=>delete s.validation.same_draft_reload_verified)],['false same-draft reload typed flag',f=>f.patch(f.directAccess.name+'/browser-events.json',s=>s.validation.same_draft_reload_verified=false)],['false persisted flag',f=>f.patch(f.directAccess.name+'/browser-events.json',s=>s.validation.persisted_draft_verified=false)],['wrong draft match',f=>f.patch(f.directAccess.name+'/browser-events.json',s=>s.validation.draft_match=false)],['wrong voice match',f=>f.patch(f.directAccess.name+'/browser-events.json',s=>s.validation.voice_match=false)],['unequal complete text',f=>f.patch(f.directAccess.name+'/browser-events.json',s=>s.validation.text_comparison.canonical_equal=false)],['wrong current binding',f=>f.input.binding={...f.input.binding,mode_epoch:99}],['wrong current voice',f=>f.input.voice_id='SYNTHETIC-other-voice'],['wrong current speech',f=>f.input.speech_text_sha256='0'.repeat(64)],['wrong current run',f=>f.input.periodic_run_id='SYNTHETIC-other-run'],['verification began before owner grant',f=>{const started_at=new Date(now-6000).toISOString();f.patch(f.directAccess.name+'/browser-attempt.json',a=>a.started_at=started_at);f.patch(f.directAccess.name+'/process/process-started.json',p=>p.started_at=started_at);}],['stale observation',f=>f.input.clock=()=>now+61000],['active verification child',f=>fs.unlinkSync(path.join(f.dir,f.directAccess.name,'process/process-exit.json'))],['real safety refusal',f=>f.patch(f.directAccess.name+'/browser-events.json',s=>s.stderr_diagnostic='security blocked')],['real ownership refusal',f=>f.patch(f.directAccess.name+'/browser-events.json',s=>s.stderr_diagnostic='tab owned by another session')],['wrong response hash',f=>f.directAccess.evidence='0'.repeat(64)],
])test('direct-access persistence refuses '+label+' without writing any receipt or permission',t=>{const f=directAccessFixture(t);change(f);const before=snapshot(f.dir);assert.equal(createProviderEditorDirectPersistence(f.directInput()),null);assert.equal(inspectProviderEditorDirectPersistence(f.input),null);assert.equal(fs.existsSync(path.join(f.dir,PROVIDER_EDITOR_DIRECT_PERSISTENCE_FILE)),false);assert.equal(fs.existsSync(path.join(f.dir,OWNER_PREVIEW_CONTINUATION_JOURNAL)),false);assert.deepEqual(snapshot(f.dir),before);});

for(const [label,signal]of [
 ['positive ready state',{ready_state:1}],['positive duration',{duration_seconds:1.25}],['media URL digest',{media_url_sha256:'7'.repeat(64)}],
])test('direct-access persistence rejects absent audio contradicted by '+label,t=>{const f=directAccessFixture(t),input={...f.directInput(),current_audio:{present:false,ready_state:0,duration_seconds:null,media_url_sha256:null,generation_in_progress:false,...signal}},before=snapshot(f.dir);assert.equal(createProviderEditorDirectPersistence(input),null);assert.deepEqual(snapshot(f.dir),before);});

for(const [label,signal]of [
 ['actual audio element',{present:true,ready_state:0}],['positive ready state',{ready_state:1}],['positive duration',{duration_seconds:1.25}],['media URL digest',{media_url_sha256:'7'.repeat(64)}],['generation in progress',{generation_in_progress:true}],
])test('direct-access v2 retains '+label+' as evidence and blocks any extra Play claim',t=>{const audio={present:null,ready_state:null,duration_seconds:null,media_url_sha256:null,generation_in_progress:false,...signal},f=directPersistenceFixture(t,{audio}),proof=inspectOwnerPreviewContinuation(f.input);assert.ok(proof);assert.deepEqual(proof.current_audio,audio);const before=snapshot(f.dir);assert.equal(claimOwnerPreviewContinuation(f.input),null);assert.equal(fs.existsSync(path.join(f.dir,OWNER_PREVIEW_CONTINUATION_JOURNAL)),false);assert.equal(fs.existsSync(path.join(f.dir,PROVIDER_EDITOR_INTENT_FILE)),false);assert.equal(fs.existsSync(path.join(f.dir,PROVIDER_EDITOR_TRANSFER_FILE)),false);assert.deepEqual(snapshot(f.dir),before);});

test('direct-access inspection rejects source bytes changed after the immutable certificate was saved',t=>{const f=directPersistenceFixture(t);f.patch(f.directAccess.name+'/browser-events.json',s=>s.validation.same_draft_reload_verified=false);const before=snapshot(f.dir);assert.equal(inspectProviderEditorDirectPersistence(f.input),null);assert.equal(inspectOwnerPreviewContinuation(f.input),null);assert.equal(claimOwnerPreviewContinuation(f.input),null);assert.deepEqual(snapshot(f.dir),before);assert.equal(fs.existsSync(path.join(f.dir,OWNER_PREVIEW_CONTINUATION_JOURNAL)),false);});
